package main

/*
#include "json.h"
*/
import "C"
import (
  "fmt"
  "sync"
  "unsafe"
)

func GetJSONRecord(key string) (string, error) {
  ck := C.CString(key)
  defer C.free(unsafe.Pointer(ck))
  var err C.int
  cstr := C.get_json_record(ck, &err)
  if cstr == nil {
    return "", fmt.Errorf("C error %d", int(err))
  }
  s := C.GoString(cstr)
  C.free(unsafe.Pointer(cstr))
  return s, nil
}

func main() {
  var wg sync.WaitGroup
  wg.Add(2)
  go func(){ defer wg.Done(); if s, e := GetJSONRecord("alpha"); e == nil { println(s) } }()
  go func(){ defer wg.Done(); if s, e := GetJSONRecord("beta"); e == nil { println(s) } }()
  wg.Wait()
}
